import React from 'react';
import { PreviewScreen } from './PreviewScreen';
import { useScrollReveal } from '../../hooks/useScrollReveal';
import m from '../../styles/marketing.module.css';
import p from '../../styles/preview.module.css';

const STEPS = [
  {
    n: '1',
    title: 'Tạo link mời bàn',
    desc: 'Chọn bàn, tên khách hoặc chiến dịch — hệ thống tạo link và mã tham gia.',
  },
  {
    n: '2',
    title: 'Gửi cho khách',
    desc: 'Copy link, gửi QR hoặc nhắn Zalo / SMS — khách không cần đăng nhập hay cài app.',
  },
  {
    n: '3',
    title: 'Biết ai đã mở',
    desc: 'Theo dõi lượt bấm link, mở trang order và vào bàn — hiển thị ngay trên màn quản lý.',
  },
];

const BENEFITS = [
  {
    tag: 'Mã mời',
    title: 'Mã tham gia bàn',
    desc: 'Khách nhập mã hoặc bấm link — vào đúng bàn, tránh nhầm order.',
  },
  {
    tag: 'Theo dõi',
    title: 'Gửi → Bấm → Vào bàn',
    desc: 'Biết link nào được mở, khách nào đã vào thực đơn.',
  },
  {
    tag: 'Đa CN',
    title: 'Link theo chi nhánh',
    desc: 'Mỗi chi nhánh có link riêng — đúng menu và tài khoản thu tiền.',
  },
];

export const LinkTrackingSection: React.FC = () => {
  const { ref, visible } = useScrollReveal<HTMLElement>();

  return (
    <section
      ref={ref}
      id="link-tracking"
      className={`${m.linkSection} ${p.reveal} ${visible ? p.revealVisible : ''}`}
      aria-label="Gửi link mời khách và theo dõi lượt mở"
    >
      <div className={m.linkInner}>
        <div className={m.linkCopy}>
          <span className={m.linkEyebrow}>Quản lý chi nhánh</span>
          <h2>Gửi link mời khách — biết ai đã mở</h2>
          <p className={m.sectionSub} style={{ textAlign: 'left', margin: '0 0 1.5rem' }}>
            Quản lý tạo link bàn hoặc chiến dịch, gửi Zalo cho khách đặt trước hoặc nhóm đi chung. Hệ thống ghi nhận{' '}
            <strong>lượt bấm link</strong>, <strong>mở trang order</strong> và <strong>vào bàn</strong> — không cần
            ghi chép Excel thủ công.
          </p>

          <ol className={m.linkSteps}>
            {STEPS.map((step) => (
              <li key={step.n} className={m.linkStep}>
                <span className={m.linkStepNum}>{step.n}</span>
                <div>
                  <strong>{step.title}</strong>
                  <p>{step.desc}</p>
                </div>
              </li>
            ))}
          </ol>

          <div className={m.grid} style={{ marginTop: '1.5rem' }}>
            {BENEFITS.map((b) => (
              <article key={b.tag} className={m.card}>
                <span className={m.tag} style={{ background: '#eef2ff', color: '#4338ca' }}>
                  {b.tag}
                </span>
                <h3>{b.title}</h3>
                <p>{b.desc}</p>
              </article>
            ))}
          </div>
        </div>

        <div className={m.linkPreview}>
          <div className={p.phoneWrap}>
            <div className={p.phoneGlow} aria-hidden />
            <div className={p.phoneFrame}>
              <div className={p.phoneNotch} aria-hidden />
              <div className={p.phoneScreen}>
                <PreviewScreen personaId="admin" screenId="links" />
              </div>
            </div>
          </div>
          <p className={m.linkPreviewCap}>Minh hoạ màn gửi link &amp; theo dõi lượt mở</p>
        </div>
      </div>
    </section>
  );
};
