import React from 'react';
import { LINM_LOGO_128 } from '../../../constants/linmBrand';
import { SEO_PILOT_BRANCH } from '../../../constants/seoSite';
import {
  PREVIEW_CART_DRAFT,
  PREVIEW_CART_ORDERED,
  PREVIEW_GUEST_LABELS,
  PREVIEW_GUEST_SESSION,
  PREVIEW_GUEST_STAFF,
  PREVIEW_MENU,
  PREVIEW_MENU_DETAIL,
  PREVIEW_PAYMENT,
  PREVIEW_SERVICE_CHIPS,
  formatVnd,
  previewCartQty,
  previewCartTotal,
} from '../../../data/pilotPreview';
import p from '../../../styles/preview.module.css';
import {
  GuestAppShell,
  GuestBottomNav,
  GuestServiceStatusPreview,
  GuestShareHeader,
} from './PreviewShell';

const L = PREVIEW_GUEST_LABELS;
const G = PREVIEW_GUEST_SESSION;
const PAY = PREVIEW_PAYMENT;

export const GuestPreviewScreen: React.FC<{ screenId: string }> = ({ screenId }) => {
  switch (screenId) {
    case 'welcome':
      return (
        <GuestAppShell
          title={L.welcomeTitle}
          badge={G.tableLabel}
          headerExtra={
            <div className={p.guestBrandBar}>
              <img src={LINM_LOGO_128} alt="Linm" className={p.guestBrandIcon} width={40} height={40} />
              <span className={p.guestBrandTenant}>{SEO_PILOT_BRANCH}</span>
            </div>
          }
          footer={
            <>
              <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
                {L.newSession}
              </button>
              <button type="button" className={`${p.btnApp} ${p.btnOutline}`} style={{ marginTop: 8 }}>
                {L.join}
              </button>
            </>
          }
        >
          <p className={p.welcomeMeta}>
            {L.waiter}: <strong>{G.waiterName}</strong>
          </p>
          <div className={p.field}>
            <label>{L.nameLabel}</label>
            <input readOnly value={G.guestName} />
          </div>
          <div className={p.field}>
            <label>{L.phoneLabel}</label>
            <input readOnly value="0901234567" />
          </div>
        </GuestAppShell>
      );

    case 'menu':
      return (
        <GuestAppShell
          title={L.menuTitle}
          headerShare={<GuestShareHeader joinCode={G.joinCode} />}
          bottomNav={<GuestBottomNav active="menu" />}
          showCallStaffFab
          cartDock={
            <div className={p.cartBar}>
              <span>🛒 {L.cartBar(previewCartQty())}</span>
              <strong>{formatVnd(previewCartTotal())}</strong>
            </div>
          }
        >
          <p className={p.menuGreeting}>{L.menuGreeting(G.guestName)}</p>
          <div className={p.menuGrid}>
            {PREVIEW_MENU.map((item) => (
              <div key={item.id} className={p.menuCard}>
                <div className={p.menuImg} style={{ background: item.accent }}>
                  {item.emoji}
                  {item.qty > 0 && <span className={p.menuBadge}>{item.qty}</span>}
                </div>
                <div className={p.menuInfo}>
                  <h4>{item.name}</h4>
                  <span className={p.menuPrice}>{formatVnd(item.price)}</span>
                </div>
              </div>
            ))}
          </div>
        </GuestAppShell>
      );

    case 'detail':
      return (
        <GuestAppShell
          title={PREVIEW_MENU_DETAIL.name}
          badge={formatVnd(PREVIEW_MENU_DETAIL.price)}
          footer={
            <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
              {L.detailAdd(formatVnd(PREVIEW_MENU_DETAIL.price))}
            </button>
          }
        >
          <div className={p.detailHero} style={{ background: PREVIEW_MENU_DETAIL.accent }}>
            <span>{PREVIEW_MENU_DETAIL.emoji}</span>
          </div>
          <p className={p.detailDesc}>{PREVIEW_MENU_DETAIL.description}</p>
          <p className={p.sectionLbl}>{L.detailAddons}</p>
          {PREVIEW_MENU_DETAIL.addons.map((a) => (
            <label key={a} className={p.addonRow}>
              <input type="checkbox" readOnly checked={a.includes('gà')} />
              <span>{a}</span>
            </label>
          ))}
          <div className={p.qtyRow}>
            <span>Số lượng</span>
            <span className={p.qtyCtrl}>− 1 +</span>
          </div>
        </GuestAppShell>
      );

    case 'cart': {
      const orderedTotal = PREVIEW_CART_ORDERED.reduce((s, l) => s + l.price, 0);
      const draftTotal = PREVIEW_CART_DRAFT.reduce((s, l) => s + l.price, 0);
      return (
        <GuestAppShell
          title={L.cartTitle}
          headerShare={<GuestShareHeader joinCode={G.joinCode} />}
          bottomNav={<GuestBottomNav active="cart" />}
          showCallStaffFab
          footer={
            <>
              <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
                {L.submitOrder}
              </button>
              <button type="button" className={`${p.btnApp} ${p.btnAmber}`} style={{ marginTop: 8 }}>
                {L.requestPayment}
              </button>
            </>
          }
        >
          <p className={p.cartSectionTitle}>{L.orderedTitle}</p>
          {PREVIEW_CART_ORDERED.map((line) => (
            <div key={line.name} className={p.cartLine}>
              <span>
                ×{line.qty} {line.name}
              </span>
              <strong>{formatVnd(line.price)}</strong>
            </div>
          ))}
          <div className={p.cartLineTotal}>
            <span>Tổng</span>
            <span>{formatVnd(orderedTotal)}</span>
          </div>
          <p className={p.cartSectionTitle}>{L.draftTitle}</p>
          {PREVIEW_CART_DRAFT.map((line) => (
            <div key={line.name} className={p.cartLine}>
              <span>
                ×{line.qty} {line.name}
              </span>
              <strong>{formatVnd(line.price)}</strong>
            </div>
          ))}
          <div className={`${p.cartLineTotal} ${p.cartLineTotalDraft}`}>
            <span>Tổng</span>
            <span>{formatVnd(draftTotal)}</span>
          </div>
          <p className={p.cartServiceTitle}>{L.serviceTitle}</p>
          <div className={p.svcChips}>
            {PREVIEW_SERVICE_CHIPS.map((c) => (
              <span key={c.label} className={p.svcChip}>
                <span className={p.svcChipIcon} aria-hidden>
                  {c.icon}
                </span>
                {c.label}
              </span>
            ))}
          </div>
        </GuestAppShell>
      );
    }

    case 'call-staff':
      return (
        <GuestAppShell
          title={L.menuTitle}
          headerShare={<GuestShareHeader joinCode={G.joinCode} />}
          bottomNav={<GuestBottomNav active="menu" />}
          showCallStaffFab
          callStaffFabBusy
        >
          <p className={p.menuGreeting}>{L.menuGreeting(G.guestName)}</p>
          <GuestServiceStatusPreview
            label={L.callStaffRequest}
            pendingLabel={L.servicePending}
          />
          <div className={p.menuGrid}>
            {PREVIEW_MENU.slice(0, 2).map((item) => (
              <div key={item.id} className={p.menuCard}>
                <div className={p.menuImg} style={{ background: item.accent }}>
                  {item.emoji}
                </div>
                <div className={p.menuInfo}>
                  <h4>{item.name}</h4>
                  <span className={p.menuPrice}>{formatVnd(item.price)}</span>
                </div>
              </div>
            ))}
          </div>
        </GuestAppShell>
      );

    case 'share':
      return (
        <GuestAppShell title={L.shareTitle} badge={G.joinCode}>
          <p className={p.shareHint}>{L.shareHint}</p>
          <div className={p.shareQrFrame}>
            <div className={p.qrPattern} aria-hidden />
            <span className={p.qrLogoCenter}>L</span>
          </div>
          <p className={p.shareCodeText}>{L.shareCode(G.joinCode, G.tableCode)}</p>
          <div className={p.shareActions}>
            <span className={p.shareChip}>Sao chép mã</span>
            <span className={p.shareChip}>Sao chép link</span>
          </div>
          <p className={p.shareGuestCount}>2 khách đang order cùng bàn</p>
        </GuestAppShell>
      );

    case 'pay':
      return (
        <GuestAppShell
          title={L.paymentTitle}
          badge={PAY.qrLabel}
          bottomNav={<GuestBottomNav active="pay" />}
          showCallStaffFab
          footer={
            <>
              <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
                {L.payButton}
              </button>
              <button type="button" className={`${p.btnApp} ${p.btnOutline}`} style={{ marginTop: 8 }}>
                {L.downloadQr}
              </button>
            </>
          }
        >
          <label className={p.checkRow}>
            <input type="checkbox" readOnly checked />
            <span>{L.confirmDishes}</span>
          </label>
          <p className={p.sectionLbl}>{L.billDefaults}</p>
          {PAY.billExtras.map((e) => (
            <div key={e} className={p.lineRowSm}>
              {e}
            </div>
          ))}
          <div className={p.payMethodTabs}>
            <span className={p.payMethodIdle}>{L.cash}</span>
            <span className={p.payMethodIdle}>{L.momo}</span>
            <span className={p.payMethodActive}>{L.bank}</span>
          </div>
          <div className={`${p.paymentInfoCard} ${p.paymentInfoCardBank}`}>
            <div className={p.qrImageWrap}>
              <div className={p.paymentQrPlaceholder}>
                <div className={p.qrPattern} aria-hidden />
                <span className={p.qrLogoCenter}>L</span>
                <span className={p.qrAmountLabel}>
                  QR thanh toán
                  <br />
                  {PAY.qrLabel}
                </span>
              </div>
            </div>
            <div className={p.paymentInfoCardMeta}>
              <div className={p.paymentQrRow}>
                <span className={p.paymentQrLabel}>{L.stk}</span>
                <span className={p.paymentQrValue}>{PAY.accountNumber}</span>
                <span className={p.paymentCopyBtn}>{L.copy}</span>
              </div>
              <div className={p.paymentQrRow}>
                <span className={p.paymentQrLabel}>{L.nameShort}</span>
                <span className={p.paymentQrValue}>{PAY.accountHolder}</span>
              </div>
            </div>
          </div>
          <div className={p.paymentNdRow}>
            <span className={p.paymentQrLabel}>{L.transferNoteShort}</span>
            <span className={p.paymentNdValue}>{PAY.transferNote}</span>
            <span className={p.paymentCopyBtn}>{L.copy}</span>
          </div>
          <p className={p.paymentMethodHint}>{L.reconcileHint}</p>
        </GuestAppShell>
      );

    case 'proof':
      return (
        <GuestAppShell
          title={L.proofTitle}
          badge={PAY.qrLabel}
          footer={
            <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
              {L.proofSubmit}
            </button>
          }
        >
          <p className={p.proofHint}>{L.proofHint}</p>
          <div className={p.proofUploadBox}>
            <span className={p.proofUploadIcon}>📷</span>
            <strong>{L.proofUpload}</strong>
            <span className={p.proofUploadSub}>{L.proofUploadHint}</span>
          </div>
          <div className={p.proofPreview}>
            <div className={p.proofThumb} aria-hidden />
            <span>Đã chọn ảnh biên lai</span>
          </div>
          <div className={p.proofMeta}>
            <div>
              <span>TK nhận</span>
              <strong>VCB · {PAY.accountNumber}</strong>
            </div>
            <div>
              <span>Số tiền</span>
              <strong>{formatVnd(PAY.amount)}</strong>
            </div>
            <div>
              <span>Nội dung</span>
              <strong>{PAY.transferNote}</strong>
            </div>
          </div>
          <p className={p.proofWaiting}>{L.proofWaiting}</p>
        </GuestAppShell>
      );

    case 'feedback':
      return (
        <GuestAppShell
          title={L.feedbackTitle}
          footer={
            <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
              {L.feedbackSubmit}
            </button>
          }
        >
          <p className={p.feedbackSuccess}>{L.feedbackSuccess}</p>
          <p className={p.sectionLbl}>{L.rateStaff}</p>
          <div className={p.scanBox}>{L.scanStaff}</div>
          <p className={p.sectionLbl}>{L.orName}</p>
          {PREVIEW_GUEST_STAFF.map((s, i) => (
            <div key={s.name} className={`${p.staffPick} ${i === 0 ? p.staffPickActive : ''}`}>
              <span>{s.name}</span>
              <span className={p.staffPickRole}>{s.role}</span>
            </div>
          ))}
          <div className={p.starRow}>
            {[1, 2, 3, 4, 5].map((n) => (
              <span key={n} className={n <= 5 ? p.starOn : p.starOff}>
                ★
              </span>
            ))}
          </div>
          <input className={p.commentInput} readOnly value="Phục vụ nhanh, món ra đúng lúc" />
        </GuestAppShell>
      );

    case 'thank-you':
      return (
        <GuestAppShell
          title={L.thankYouTitle}
          footer={
            <button type="button" className={`${p.btnApp} ${p.btnGreen}`}>
              {L.thankYouDone}
            </button>
          }
        >
          <div className={p.thankYouIcon}>✓</div>
          <p className={p.thankYouSub}>{L.thankYouSubtitle}</p>
          <p className={p.thankYouClosed}>{L.thankYouClosed}</p>
        </GuestAppShell>
      );

    default:
      return null;
  }
};
