const K = PREVIEW_KITCHEN_LABELS;

const kitchenTicketClass = (status: 'NEW' | 'PREP' | 'DONE'): string => {
  if (status === 'NEW') return p.kTicketNew;
  if (status === 'DONE') return p.kTicketDone;
  return '';
};

const LINK_EVENT_CLASS: Record<string, string> = {
  sent: p.linkEventsent,
  click: p.linkEventclick,
  open: p.linkEventopen,
  join: p.linkEventjoin,
};

export const WaiterPreviewScreen: React.FC<{ screenId: string }> = ({ screenId }) => {
  const shift = PREVIEW_WAITER_SHIFT;
  const wl = PREVIEW_WAITER_LABELS;

  switch (screenId) {
    case 'shift':
      return (
        <WaiterShell
          title={`${shift.staffName} · ${shift.shiftLabel}`}
          badge={`${shift.assignedTableCount} ${wl.tables}`}
        >
          <div className={`${p.wCard} ${p.wCardNew}`}>
            <div className={p.wRow}>
              <strong>📋 {wl.pendingOrders}</strong>
              <span className={p.countBadge}>{shift.pendingOrderCount}</span>
            </div>
            <div className={p.wMeta}>{wl.pendingOrdersMeta}</div>
          </div>
          <div className={`${p.wCard} ${p.wCardUrgent}`}>
            <div className={p.wRow}>
              <strong>🙋 {wl.pendingService}</strong>
              <span className={`${p.countBadge} ${p.countBadgeAmber}`}>{shift.pendingServiceCount}</span>
            </div>
            <div className={p.wMeta}>{wl.pendingServiceMeta}</div>
          </div>
          <div className={p.wCard}>
            <div className={p.wRow}>
              <strong>🧹 {wl.cleanTable}</strong>
              <span className={p.countBadge}>{shift.cleanTableCount}</span>
            </div>
            <div className={p.wMeta}>{wl.cleanTableMeta}</div>
          </div>
          <p className={p.wHint}>{wl.multiStaffHint}</p>
          <span className={p.wBtnOutline}>🗺 {wl.floorTitle}</span>
        </WaiterShell>
      );

    case 'floor':
      return (
        <FnbFloorShell title={wl.floorTitle} badge="5/16">
          <div className={p.statRow}>
            <div className={p.statBox}>
              <div className={p.statNum}>5</div>
              <div className={p.statLbl}>Bàn có khách</div>
            </div>
            <div className={p.statBox}>
              <div className={p.statNum}>3</div>
              <div className={p.statLbl}>Chờ thanh toán</div>
            </div>
          </div>
          <div className={p.tableGrid}>
            {PREVIEW_TABLES.map((t) => (
              <div key={t.number} className={`${p.tableCell} ${t.status === 'busy' ? p.tableBusy : ''}`}>
                <div className={p.tableNum}>{t.number}</div>
                <div className={p.tableSub}>{t.sub}</div>
              </div>
            ))}
          </div>
        </FnbFloorShell>
      );

    case 'orders':
      return (
        <WaiterShell title="Xác nhận order" back>
          {PREVIEW_WAITER_ORDERS.map((o) => (
            <div key={o.table} className={`${p.wCard} ${p.wCardNew}`}>
              <strong>
                {o.table} · {o.customer}
              </strong>
              <div className={p.wMeta} style={{ whiteSpace: 'pre-line' }}>
                {o.lines.join('\n')}
              </div>
              <div className={p.wMeta}>
                <strong>{formatVnd(o.total)}</strong>
              </div>
              <div className={p.wActions}>
                <button type="button" className={p.wBtnGreen}>
                  {o.action}
                </button>
              </div>
            </div>
          ))}
        </WaiterShell>
      );

    case 'service':
      return (
        <WaiterShell title="Xác nhận phục vụ" back>
          <div className={p.scanBox}>📷 Scan mã request / bàn</div>
          <div className={p.wNav}>
            <span className={`${p.wNavPill} ${p.wNavPillActive}`}>Tất cả</span>
            <span className={p.wNavPill}>Order</span>
            <span className={p.wNavPill}>Gọi thêm</span>
            <span className={p.wNavPill}>Lau bàn</span>
          </div>
          {PREVIEW_WAITER_SERVICE.map((s) => (
            <div key={s.label} className={`${p.wCard} ${s.urgent ? p.wCardUrgent : ''}`}>
              <strong>
                {s.meta.split(' · ')[0]} · {s.icon} {s.label}
              </strong>
              <div className={p.wMeta}>{s.meta}</div>
              <div className={p.wActions}>
                <button type="button" className={p.wBtnGreen}>
                  {s.label === 'Thanh toán' ? '→ Thu ngân' : '✓ Đã phục vụ'}
                </button>
              </div>
            </div>
          ))}
        </WaiterShell>
      );

    case 'clean':
      return (
        <WaiterShell title="Dọn bàn" back>
          {PREVIEW_WAITER_CLEAN.map((t) => (
            <div
              key={t.table}
              className={`${p.wCard} ${t.status === 'done' ? p.wCardDone : ''}`}
            >
              <strong>{t.table}</strong>
              <div className={p.wMeta}>{t.meta}</div>
              {t.status === 'pending' && (
                <div className={p.wActions}>
                  <button type="button" className={p.wBtnGreen}>
                    ✓ Đã dọn bàn
                  </button>
                </div>
              )}
            </div>
          ))}
        </WaiterShell>
      );

    default:
      return null;
  }
};

/** Parity @linm/fnb-kitchen KitchenDisplayPage + fnbPage.module.css */
export const KitchenPreviewScreen: React.FC<{ screenId: string }> = ({ screenId }) => {
  if (screenId !== 'board') return null;
  return (
    <div className={`${p.kitchenRoot} ${p.previewFill}`} data-testid="kitchen-preview-display">
      <div className={p.kHeader}>
        <h2>
          👨‍🍳 {K.title} · {SEO_PILOT_BRANCH}
        </h2>
        <span className={p.kLive}>{K.live}</span>
      </div>
      <div className={p.kBody}>
        {PREVIEW_KITCHEN.map((ticket) => (
          <div
            key={ticket.tableLabel}
            className={[p.kTicket, kitchenTicketClass(ticket.status)].filter(Boolean).join(' ')}
          >
            <div className={p.kTable}>{ticket.tableLabel}</div>
            <div className={p.kTime}>
              {K.minutesAgo(ticket.minutesAgo)} · {ticket.status}
            </div>
            <div className={p.kLines}>
              {ticket.lines.map((line) => (
                <div key={line}>{line}</div>
              ))}
            </div>
            {ticket.status !== 'DONE' && (
              <div className={p.kActions}>
                {ticket.status === 'NEW' ? (
                  <button type="button" className={`${p.kBtn} ${p.kBtnConfirm}`}>
                    {K.accept}
                  </button>
                ) : (
                  <button type="button" className={`${p.kBtn} ${p.kBtnDone}`}>
                    {K.done}
                  </button>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

