import React, { useRef } from 'react';
import p from '../../styles/preview.module.css';

const SWIPE_MIN_PX = 48;

export interface PreviewPhoneNavProps {
  onPrev: () => void;
  onNext: () => void;
  screenKey: string;
  children: React.ReactNode;
}

/** Vuốt ngang / bấm vùng trái-phải / mũi tên — chuyển màn demo */
export const PreviewPhoneNav: React.FC<PreviewPhoneNavProps> = ({
  onPrev,
  onNext,
  screenKey,
  children,
}) => {
  const touchRef = useRef<{ x: number; y: number } | null>(null);

  const onTouchStart = (e: React.TouchEvent) => {
    const t = e.changedTouches[0];
    touchRef.current = { x: t.clientX, y: t.clientY };
  };

  const onTouchEnd = (e: React.TouchEvent) => {
    const start = touchRef.current;
    touchRef.current = null;
    if (!start) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - start.x;
    const dy = t.clientY - start.y;
    if (Math.abs(dx) < SWIPE_MIN_PX || Math.abs(dx) < Math.abs(dy)) return;
    if (dx < 0) onNext();
    else onPrev();
  };

  const onScreenClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = (e.clientX - rect.left) / rect.width;
    if (ratio < 0.28) onPrev();
    else if (ratio > 0.72) onNext();
  };

  const pauseAnd = (fn: () => void) => (e: React.MouseEvent) => {
    e.stopPropagation();
    fn();
  };

  return (
    <div className={p.phoneSlideStage}>
      <button
        type="button"
        className={p.phoneNavBtn}
        aria-label="Màn trước"
        onClick={pauseAnd(onPrev)}
      >
        ‹
      </button>

      <div className={p.phoneFrame}>
        <div className={p.phoneNotch} aria-hidden />
        <div
          className={p.phoneScreen}
          role="group"
          aria-roledescription="slide"
          aria-label="Vuốt hoặc bấm cạnh trái/phải để đổi màn demo"
          onClick={onScreenClick}
          onTouchStart={onTouchStart}
          onTouchEnd={onTouchEnd}
        >
          <div key={screenKey} className={p.screenEnter}>
            {children}
          </div>
          <button
            type="button"
            className={p.phoneTapPrev}
            aria-label="Màn trước"
            tabIndex={-1}
            onClick={pauseAnd(onPrev)}
          />
          <button
            type="button"
            className={p.phoneTapNext}
            aria-label="Màn sau"
            tabIndex={-1}
            onClick={pauseAnd(onNext)}
          />
        </div>
      </div>

      <button
        type="button"
        className={p.phoneNavBtn}
        aria-label="Màn sau"
        onClick={pauseAnd(onNext)}
      >
        ›
      </button>
    </div>
  );
};
