import React, { useCallback, useEffect, useRef, useState } from 'react';

import { PERSONAS, type PersonaId } from '../../data/pilotPreview';

import { useScrollReveal } from '../../hooks/useScrollReveal';

import { PreviewPhoneNav } from './PreviewPhoneNav';
import { PreviewScreen } from './PreviewScreen';

import p from '../../styles/preview.module.css';

const CYCLE_MS = 4500;
const PAUSE_MS = 12000;

export const ProductShowcase: React.FC = () => {
  const { ref, visible } = useScrollReveal<HTMLElement>();
  const [personaId, setPersonaId] = useState<PersonaId>('guest');
  const [screenIdx, setScreenIdx] = useState(0);
  const [paused, setPaused] = useState(false);

  const persona = PERSONAS.find((x) => x.id === personaId) ?? PERSONAS[0];
  const screen = persona.screens[screenIdx] ?? persona.screens[0];

  const pauseTimerRef = useRef<ReturnType<typeof setTimeout>>();

  const pauseAuto = useCallback(() => {
    if (pauseTimerRef.current) clearTimeout(pauseTimerRef.current);
    setPaused(true);
    pauseTimerRef.current = setTimeout(() => setPaused(false), PAUSE_MS);
  }, []);

  const nextScreen = useCallback(() => {
    setScreenIdx((i) => {
      if (i + 1 < persona.screens.length) return i + 1;
      const pi = PERSONAS.findIndex((x) => x.id === personaId);
      const nextPersona = PERSONAS[(pi + 1) % PERSONAS.length];
      setPersonaId(nextPersona.id);
      return 0;
    });
  }, [persona.screens.length, personaId]);

  const prevScreen = useCallback(() => {
    setScreenIdx((i) => {
      if (i > 0) return i - 1;
      const pi = PERSONAS.findIndex((x) => x.id === personaId);
      const prevPersona = PERSONAS[(pi - 1 + PERSONAS.length) % PERSONAS.length];
      setPersonaId(prevPersona.id);
      return prevPersona.screens.length - 1;
    });
  }, [personaId]);

  const onNext = useCallback(() => {
    pauseAuto();
    nextScreen();
  }, [pauseAuto, nextScreen]);

  const onPrev = useCallback(() => {
    pauseAuto();
    prevScreen();
  }, [pauseAuto, prevScreen]);

  useEffect(() => {
    if (paused || !visible) return;
    const t = setInterval(nextScreen, CYCLE_MS);
    return () => clearInterval(t);
  }, [paused, visible, nextScreen]);

  const onPersona = (id: PersonaId) => {
    setPersonaId(id);
    setScreenIdx(0);
    pauseAuto();
  };

  return (
    <section
      ref={ref}
      className={`${p.showcase} ${p.reveal} ${visible ? p.revealVisible : ''}`}
      id="product-showcase"
      aria-label="Giao diện ứng dụng Linm Soft"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div className={p.showcaseInner}>
        <h2>Giao diện thật — như khi vận hành tại quán</h2>
        <p className={p.showcaseSub}>
          Chọn vai trò bên dưới để xem từng màn hình — dùng cùng dữ liệu mẫu với phần mềm đang triển khai.
        </p>

        <div className={p.personaBar} role="tablist">
          {PERSONAS.map((item) => (
            <button
              key={item.id}
              type="button"
              role="tab"
              aria-selected={personaId === item.id}
              className={`${p.personaBtn} ${personaId === item.id ? p.personaBtnActive : ''}`}
              onClick={() => onPersona(item.id)}
            >
              <span>{item.icon}</span>
              {item.label}
            </button>
          ))}
        </div>

        <p className={p.roleHint}>{persona.roleHint}</p>

        <div className={p.screenDots}>
          {persona.screens.map((s, i) => (
            <button
              key={s.id}
              type="button"
              className={`${p.dot} ${i === screenIdx ? p.dotActive : ''}`}
              aria-label={s.label}
              onClick={() => {
                setScreenIdx(i);
                pauseAuto();
              }}
            />
          ))}
        </div>

        <p className={p.screenLabel}>{screen.label}</p>
        <p className={p.screenNavHint}>Vuốt ngang trên điện thoại · bấm cạnh trái/phải hoặc mũi tên để xem màn trước/sau</p>

        <div className={p.stage}>
          <div className={p.phoneWrap}>
            <div className={p.phoneGlow} aria-hidden />
            <PreviewPhoneNav
              screenKey={`${personaId}-${screen.id}`}
              onPrev={onPrev}
              onNext={onNext}
            >
              <PreviewScreen personaId={personaId} screenId={screen.id} />
            </PreviewPhoneNav>
          </div>

          <aside className={p.sideInfo}>
            <strong>{persona.label}</strong>
            <p>{persona.roleHint}</p>
          </aside>
        </div>
      </div>
    </section>
  );
};
