import React from 'react';
import { GuestPreviewScreen } from './preview/GuestPreviewScreens';
import {
  AdminPreviewScreen,
  KitchenPreviewScreen,
  ReportsPreviewScreen,
  WaiterPreviewScreen,
} from './preview/StaffPreviewScreens';
import p from '../../styles/preview.module.css';

interface PreviewScreenProps {
  personaId: string;
  screenId: string;
}

export const PreviewScreen: React.FC<PreviewScreenProps> = ({ personaId, screenId }) => {
  const key = `${personaId}-${screenId}`;

  let content: React.ReactNode = null;
  if (personaId === 'guest') content = <GuestPreviewScreen screenId={screenId} />;
  else if (personaId === 'waiter') content = <WaiterPreviewScreen screenId={screenId} />;
  else if (personaId === 'kitchen') content = <KitchenPreviewScreen screenId={screenId} />;
  else if (personaId === 'admin') content = <AdminPreviewScreen screenId={screenId} />;
  else if (personaId === 'reports') content = <ReportsPreviewScreen screenId={screenId} />;

  if (!content) return null;

  return (
    <div key={key} className={p.previewFill}>
      {content}
    </div>
  );
};
