export function formatVnd(n: number): string {
  return `${n.toLocaleString('vi-VN')}₫`;
}

export function previewCartTotal(): number {
  return PREVIEW_MENU.reduce((s, m) => s + m.price * m.qty, 0);
}

export function previewCartQty(): number {
  return PREVIEW_MENU.reduce((s, m) => s + m.qty, 0);
}

export function previewCartOrderedTotal(): number {
  return PREVIEW_CART_ORDERED.reduce((s, l) => s + l.price, 0);
}
