import React from 'react';
import { PREVIEW_GUEST_LABELS } from '../../../data/pilotPreview';
import p from '../../../styles/preview.module.css';

const BOTTOM_NAV_ITEMS = [
  { id: 'menu' as const, icon: '📋', label: PREVIEW_GUEST_LABELS.bottomNav.menu },
  { id: 'cart' as const, icon: '🛒', label: PREVIEW_GUEST_LABELS.bottomNav.cart },
  { id: 'pay' as const, icon: '💳', label: PREVIEW_GUEST_LABELS.bottomNav.pay },
];

/** Parity @linm/fnb-guest GuestBottomNav */
export const GuestBottomNav: React.FC<{ active?: 'menu' | 'cart' | 'pay' }> = ({ active = 'menu' }) => (
  <nav className={p.bottomNav} aria-label="Điều hướng khách" data-testid="guest-preview-bottom-nav">
    {BOTTOM_NAV_ITEMS.map((item) => (
      <span
        key={item.id}
        className={[p.navItem, active === item.id ? p.navItemActive : ''].filter(Boolean).join(' ')}
        aria-current={active === item.id ? 'page' : undefined}
      >
        <span className={p.navIcon} aria-hidden>
          {item.icon}
        </span>
        {item.label}
      </span>
    ))}
  </nav>
);

/** Parity GuestSharePanel header strip */
export const GuestShareHeader: React.FC<{ joinCode: string }> = ({ joinCode }) => (
  <div className={p.headerShareWrap}>
    <span className={p.headerJoinCode}>{joinCode}</span>
    <span className={p.headerShareBtn}>
      <span className={p.headerShareIcon} aria-hidden>
        ↗
      </span>
      {PREVIEW_GUEST_LABELS.shareBtn}
    </span>
  </div>
);

/** Parity GuestServiceStatusPanel — một request chờ xác nhận */
export const GuestServiceStatusPreview: React.FC<{
  icon?: string;
  label: string;
  pendingLabel: string;
}> = ({ icon = '🛎', label, pendingLabel }) => (
  <div className={p.serviceStatusPanel} data-testid="guest-preview-service-status">
    <p className={p.cartSectionTitle}>{PREVIEW_GUEST_LABELS.serviceStatusTitle}</p>
    <div className={p.serviceStatusCard}>
      <div className={p.serviceStatusHead}>
        <span>
          {icon} {label}
        </span>
        <span className={p.serviceStatusBadge}>{pendingLabel}</span>
      </div>
    </div>
  </div>
);

/** Parity @linm/fnb-guest GuestCallStaffFab (static preview) */
export const GuestCallStaffFab: React.FC<{
  busy?: boolean;
  aboveFooter?: boolean;
  aboveBottomNav?: boolean;
  aboveCart?: boolean;
}> = ({ busy = false, aboveFooter = false, aboveBottomNav = false, aboveCart = false }) => (
  <button
    type="button"
    className={[
      p.callStaffFab,
      aboveCart && !aboveFooter ? p.callStaffFabAboveCart : '',
      aboveBottomNav && !aboveFooter && !aboveCart ? p.callStaffFabAboveNav : '',
      aboveFooter ? p.callStaffFabAboveFooter : '',
      busy ? p.callStaffFabBusy : '',
    ]
      .filter(Boolean)
      .join(' ')}
    aria-label={PREVIEW_GUEST_LABELS.callStaffFabAria}
    data-testid="guest-preview-call-staff-fab"
    disabled={busy}
  >
    <span className={p.callStaffFabIcon} aria-hidden>
      🛎
    </span>
    <span className={p.callStaffFabLabel}>{PREVIEW_GUEST_LABELS.callStaffFab}</span>
  </button>
);

/** @deprecated use GuestCallStaffFab */
export const CallStaffFab = GuestCallStaffFab;

export const GuestAppShell: React.FC<{
  title: string;
  badge?: string;
  headerExtra?: React.ReactNode;
  /** Mã session + Chia sẻ — cùng hàng tiêu đề (GuestSharePanel) */
  headerShare?: React.ReactNode;
  footer?: React.ReactNode;
  /** Thanh giỏ cố định trên bottom nav (menu) */
  cartDock?: React.ReactNode;
  bottomNav?: React.ReactNode;
  /** Session screens — floating Gọi NV FAB */
  showCallStaffFab?: boolean;
  callStaffFabBusy?: boolean;
  /** @deprecated use showCallStaffFab */
  fab?: boolean;
  children: React.ReactNode;
}> = ({
  title,
  badge,
  headerExtra,
  headerShare,
  footer,
  cartDock,
  bottomNav,
  showCallStaffFab,
  callStaffFabBusy,
  fab,
  children,
}) => {
  const withFab = showCallStaffFab ?? fab ?? false;

  return (
    <div
      className={[
        p.appRoot,
        p.previewFill,
        footer ? p.appRootHasFooter : '',
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {headerExtra}
      <div className={p.appHeader}>
        <h3>{title}</h3>
        {headerShare ?? (badge ? <span className={p.badge}>{badge}</span> : null)}
      </div>
      <div className={[p.appBody, withFab ? p.appBodyWithFab : ''].filter(Boolean).join(' ')}>
        {children}
      </div>
      {cartDock ? <div className={p.cartDock}>{cartDock}</div> : null}
      {footer ? <div className={p.appFooter}>{footer}</div> : null}
      {withFab ? (
        <GuestCallStaffFab
          busy={callStaffFabBusy}
          aboveFooter={!!footer}
          aboveCart={!!cartDock}
          aboveBottomNav={!!bottomNav}
        />
      ) : null}
      {bottomNav}
    </div>
  );
};

